package dev.thefoolish.generated.anishelf;
import android.widget.*;import java.util.*;
public final class ProvidersActivity extends AppScreen{protected void render(){title("Extensions");subtitle("Built-in reviewed providers are ready immediately. Repository providers remain user-manageable and isolated.");body.addView(text("Built in",18,true));for(MediaProvider p:BuiltInProviderCatalog.providers()){body.addView(text(p.displayName()+" · ENABLED",16,true));subtitle(p.health());}body.addView(text("Repository extensions",18,true));List<ExtensionRecord> known=new ExtensionManager(this).known();if(known.isEmpty())subtitle("No additional repository extensions synced yet.");for(ExtensionRecord x:known){body.addView(text(x.name+" · "+x.version+" · "+x.state,15,true));Button toggle=button(x.state==ExtensionRecord.State.ENABLED?"Disable":"Enable");toggle.setOnClickListener(v->{ExtensionRecord.State next=x.state==ExtensionRecord.State.ENABLED?ExtensionRecord.State.DISABLED:ExtensionRecord.State.ENABLED;new ExtensionManager(this).setState(x.id,next);recreate();});body.addView(toggle);subtitle("Source: "+x.repoUrl);}Button repos=button("Repositories");repos.setOnClickListener(v->AppNavigator.open(this,RepositoriesActivity.class));body.addView(repos);nav();}}
